    margin-right: auto;
    border-radius: 8px;
    border-right: 4px solid #ccc;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  }
</style>', '<h2 id="who-was-eleanor-hadden">Who was Eleanor Hadden?</h2>
