INSERT OR REPLACE INTO board_members (id, name, role, bio, image, group_name, sort_order, active) VALUES ('taj-sabet', 'Taj Sabet', 'Chairman', 'Trilingual businessman and entrepreneur, serving as Chairman for six years. Great-grandson of Shu''a''u''lláh ''A''lá''í, one of the two Hands of the Cause to whom the institute is dedicated.', 'https://drbi.s3.amazonaws.com/uploads/2024-05-31-default-slug-taj_profile.webp', 'board', 0, 1);
INSERT OR REPLACE INTO board_members (id, name, role, bio, image, group_name, sort_order, active) VALUES ('marguerite-sears', 'Marguerite Sears', 'Board Member', 'Namesake and granddaughter of the founder of DRBI. Specializes in envisioning events and activities that share Desert Rose with the world.', 'https://drbi.s3.amazonaws.com/uploads/2024-05-31-default-slug-marguerite_profile.webp', 'board', 1, 1);
INSERT OR REPLACE INTO board_members (id, name, role, bio, image, group_name, sort_order, active) VALUES ('dwight-cox', 'Dwight Cox', 'Vice-Chair & Interim Treasurer', 'Joined the board in 2015. Now retired from his Aviation business and devoting his time to DRBI''s Agriculture program, reclaiming the desert as viable land.', 'https://drbi.s3.amazonaws.com/uploads/2024-05-31-default-slug-dwight_profile.webp', 'board', 2, 1);
INSERT OR REPLACE INTO board_members (id, name, role, bio, image, group_name, sort_order, active) VALUES ('chad-jones', 'Chad Jones', 'Executive Director', 'Alaskan fisherman and software developer with a deep interest in Bahá''í education. Believes the guidance of the Guardian speaks not only to the past, but to our future.', 'https://drbi.s3.amazonaws.com/uploads/2024-06-02-default-slug-IMG_4876.JPG', 'board', 3, 1);
INSERT OR REPLACE INTO board_members (id, name, role, bio, image, group_name, sort_order, active) VALUES ('pete-smith', 'Pete Smith', 'Board Member', NULL, 'https://drbi.s3.amazonaws.com/uploads/2024-05-31-default-slug-pete_smith.webp', 'board', 4, 1);
